#include "shell/image_provider_qt.hpp"
#if defined(SQUIFLOW_WITH_QT)
#include <QBuffer>
#include <QImageReader>
namespace squiflow::shell{ImageProviderQt::ImageProviderQt(std::shared_ptr<PreviewSource>s,std::shared_ptr<ThumbnailCache>c):QQuickImageProvider(Image),source_(std::move(s)),cache_(std::move(c)){}bool ImageProviderQt::avif_available(){return QImageReader::supportedImageFormats().contains("avif");}QImage ImageProviderQt::requestImage(const QString&q,QSize*out,const QSize&requested){auto id=q.toStdString();auto r=source_->resolve(id);QImage image;if(r&&r->id==id&&ThumbnailCache::valid({id,r->hash})){if(auto p=cache_->lookup({id,r->hash}))image.load(QString::fromStdString(p->string()));if(image.isNull()){QImageReader reader(QString::fromStdString(r->path));reader.setAutoTransform(true);image=reader.read();if(!image.isNull()){auto size=requested.isValid()?requested:QSize(256,256);size.setWidth(std::min(size.width(),2048));size.setHeight(std::min(size.height(),2048));image=image.scaled(size,Qt::KeepAspectRatio,Qt::SmoothTransformation);QByteArray bytes;QBuffer b(&bytes);b.open(QIODevice::WriteOnly);image.save(&b,"PNG");cache_->store({id,r->hash},{reinterpret_cast<const std::uint8_t*>(bytes.data()),static_cast<std::size_t>(bytes.size())});}}}if(image.isNull()){source_->failed(id,"image.error.unsupported_or_missing");image=QImage(128,128,QImage::Format_ARGB32);image.fill(QColor("#e4e7ec"));}if(out)*out=image.size();return image;}}
#endif
